INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('aedbeecd-c73b-55e8-a050-ed9cfc09bdf8'::uuid, '698b5da1-7d5f-5bcd-84cc-5aea68675ec7'::uuid, 'Construction d''un immeuble résidentiel R+4 – Gros œuvre', 'Réalisation par Sobenbac du gros œuvre d''un immeuble R+4 à usage mixte : locaux commerciaux au rez-de-chaussée et 4 étages d''appartements.', '["https://lechantier.ma/uploads/media/0c4fbeb37773.webp", "https://lechantier.ma/uploads/media/e82a9696e814.webp", "https://lechantier.ma/uploads/media/5327e4768484.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/0c4fbeb37773.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('114a740c-d2c2-576e-8871-e798c1aa7a74'::uuid, '698b5da1-7d5f-5bcd-84cc-5aea68675ec7'::uuid, 'Réalisation Gros Œuvre - Immeuble R+2', 'Construction complète du gros œuvre d''un immeuble R+2 signée SOBENBAC. Ce projet met en valeur notre expertise en béton armé, maçonnerie de précision et architecture moderne. Structure solide, finitions soignées et respect des délais : voilà notre signature. 🏗️ ✨ Poteaux, poutres, planchers hourdis, escaliers et façade contemporaine réalisés avec le plus grand soin. 📞 Contactez-nous pour votre projet de construction !', '["https://lechantier.ma/uploads/media/cbe2b15c3f5e.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/cbe2b15c3f5e.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
