INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6fbe03f8-3dd8-5fb8-8dc9-fb9e0a61fdf7'::uuid, '806ea1af-319a-5d04-b872-5b4308c67b99'::uuid, 'Coverage areas', 'Marrakech', '[]'::jsonb, NULL, 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('bce0aca9-6e49-5b1b-a4a5-bb5baf51cd3f'::uuid, '74c1a00e-2d80-539d-b5e8-89c2c4e67943'::uuid, 'Hôtel Vichy (Hôtel The View Bouznika)', 'Nous avons réalisé une rénovation complète alliant carrelage effet marbre, peinture de qualité et nettoyage de chantier soigné. Chaque étape a été exécutée avec rigueur et précision, garantissant un rendu moderne et durable. Un travail professionnel qui reflète notre engagement pour la qualité et la satisfaction du client.', '["https://lechantier.ma/uploads/media/84be27f4c723.webp", "https://lechantier.ma/uploads/media/3f4ba74b8040.webp", "https://lechantier.ma/uploads/media/a0869f4b2958.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/84be27f4c723.webp', 'Salé', (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('c6166c65-4126-5df1-88f0-301d7f68a421'::uuid, '74c1a00e-2d80-539d-b5e8-89c2c4e67943'::uuid, 'Tizi Projet', 'Pour le projet Tizi, Manobra s''est occupée de tous les travaux de finition intérieure, tels que la plâtrerie, les cloisons en BA13, les enduits et la peinture. Elle a également réalisé la menuiserie intérieure et extérieure en bois et aluminium, ainsi que la mise en place des façades et vitrages en verre.', '["https://lechantier.ma/uploads/media/e34e7f9a889e.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/e34e7f9a889e.webp', 'Salé', (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('696f62f6-c6ab-5d7b-9924-0b10829a127c'::uuid, '74c1a00e-2d80-539d-b5e8-89c2c4e67943'::uuid, 'Réalisation — MANOBRA', NULL, '["https://lechantier.ma/uploads/media/3f4ba74b8040.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/3f4ba74b8040.webp', 'Salé', (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('1d7766fa-06d4-5ab6-8774-539ed4650ea5'::uuid, '74c1a00e-2d80-539d-b5e8-89c2c4e67943'::uuid, 'Réalisation — MANOBRA', NULL, '["https://lechantier.ma/uploads/media/a0869f4b2958.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/a0869f4b2958.webp', 'Salé', (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('bcebd33e-984a-5937-9db9-74af98d4629c'::uuid, '9c54a2c3-a81d-565e-b806-21f065832f54'::uuid, 'Villa à Harhoura', 'Découvrez cette villa contemporaine réalisée par notre équipe dans le cadre de nos travaux de gros œuvre. Cette construction aux lignes modernes se distingue par ses volumes généreux et sa structure robuste, conçue pour offrir une base solide aux futures finitions architecturales. Alliant savoir-faire technique et exigence de qualité, ce projet reflète notre engagement à réaliser des ouvrages durables, fonctionnels et esthétiques, répondant aux attentes les plus élevées de nos clients.', '["https://lechantier.ma/uploads/media/96a33b01c819.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/96a33b01c819.webp', 'Témara', (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('bcb80033-f6b8-522b-83c0-5138b9437496'::uuid, '9c54a2c3-a81d-565e-b806-21f065832f54'::uuid, 'construction Piscine', 'Chaque piscine est une réalisation sur mesure, conçue avec soin pour garantir robustesse, fonctionnalité et esthétique. Sur ce projet, notre équipe est intervenue dans la réalisation du gros œuvre d’une piscine au design contemporain et aux formes personnalisées. Les travaux comprenaient le terrassement, la réalisation de la structure en béton, l’élévation des murs, la création des banquettes ainsi que l’ensemble des finitions préparatoires.', '[]'::jsonb, NULL, 'Témara', (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('93b20284-bad4-5f6d-a3e9-fd2ff9fbeb7d'::uuid, '7653dfdc-92ad-5a8f-b4be-c714fae88f31'::uuid, 'TOHFA', 'Le programme TOHFA est un programme exclusif et limité, réservé à la réalisation de 30 villas uniquement. Son objectif est d’offrir aux clients un accompagnement hautement professionnel et de concevoir de véritables œuvres architecturales, en plaçant la qualité d’exécution au cœur de chaque projet.', '["https://lechantier.ma/uploads/media/3f5927739842.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/3f5927739842.webp', 'Kénitra', (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d9bb319b-1fba-56e2-a424-115ffa3e060d'::uuid, '7653dfdc-92ad-5a8f-b4be-c714fae88f31'::uuid, 'MAHALI', 'TOHFA Mahali est une offre de finition et d’aménagement haut de gamme dédiée aux espaces de travail. Elle conçoit des environnements professionnels fonctionnels, élégants et identitaires, en alliant architecture intérieure, qualité des matériaux et maîtrise d’exécution, afin d’optimiser le confort, la performance et l’image de l’entreprise.', '[]'::jsonb, NULL, 'Kénitra', (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a42890f8-3b31-5dcd-b19a-357372944c90'::uuid, '9005ca5c-7b0e-594d-a022-8865c5363c99'::uuid, 'bungalow', 'travaux d''amenagement d''un bungalow clé en main', '["https://lechantier.ma/uploads/media/ecd24ed9c855.webp", "https://lechantier.ma/uploads/media/4308ead703a0.webp", "https://lechantier.ma/uploads/media/8695fae17326.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ecd24ed9c855.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1));
