INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('1268180a-a374-5b64-aae1-489fd93283b7'::uuid, '5e55782c-a927-554d-824f-b302ac8eeab1'::uuid, 'Démolition D''une Villa RDC', 'نحن شركة متخصصة في أشغال هدم الفلل والبنايات، نوفر خدمات متكاملة تشمل: هدم آمن وفق القوانين والمعايير الجاري بها العمل فرز ونقل الردميات إلى المطرح المخصص تنظيف شامل لموقع الورش بعد الانتهاء الالتزام بالجودة واحترام الآجال المحددة 📍 خدماتنا متوفرة في جميع أنحاء المغرب.', '["https://lechantier.ma/uploads/media/eae2489626ab.webp", "https://lechantier.ma/uploads/media/5b052b505771.webp", "https://lechantier.ma/uploads/media/72312e270ab2.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/eae2489626ab.webp', 'Khouribga', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('63e661f6-ccdd-5d99-ad23-06e040722ae0'::uuid, '5e55782c-a927-554d-824f-b302ac8eeab1'::uuid, 'Construction d''un R+2', '🏗 بناء عمارة R+2 نوفر لكم خدمة بناء عمارة عصرية تتكون من طابق أرضي + طابقين، بتصميم يجمع بين المتانة والجمالية. ✔ الطابق الأرضي: محلات أو مرائب ✔ الطوابق العليا: شقق أو مكاتب مريحة وعملية عمارة مثالية لـ الاستثمار أو السكن العائلي، مع تشطيبات عصرية وجودة عالية في البناء. 📞 تواصلوا معنا لتحقيق مشروعكم بأفضل المعايير. 0660449918', '["https://lechantier.ma/uploads/media/1f8d161ce0b0.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/1f8d161ce0b0.webp', 'Khouribga', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
